import React from 'react';

const PublicoObjetivo = () => {
    return (
        <section id="publico-objetivo">
            <h2>Público Objetivo</h2>
            <p>
                El proyecto está dirigido principalmente a estudiantes de secundaria, estudiantes universitarios, jóvenes entre los 15 y 30 años, así como a la ciudadanía interesada en la historia y la democracia costarricense.
            </p>
            <p>
                La elección de este público responde a la necesidad de acercar el conocimiento histórico a sectores de la población que, en muchos casos, poseen información limitada sobre la dictadura de los hermanos Tinoco y su relevancia en el desarrollo democrático del país. En particular, la población joven constituye un grupo prioritario, debido a que se encuentra en una etapa clave para la formación de pensamiento crítico, identidad cívica y participación ciudadana.
            </p>
            <p>
                Además, al involucrar a estudiantes y ciudadanía interesada, la propuesta permite ampliar el alcance de la memoria histórica más allá del aula, fomentando la reflexión social y el interés por los procesos históricos nacionales.
            </p>
        </section>
    );
};

export default PublicoObjetivo;
